static int nct6694_usb_probe(struct usb_interface *iface,
			     const struct usb_device_id *id)
{
	struct usb_device *udev = interface_to_usbdev(iface);
	struct usb_endpoint_descriptor *int_endpoint;
	struct usb_host_interface *interface;
	struct device *dev = &iface->dev;
	struct nct6694 *nct6694;
	int ret;

	nct6694 = devm_kzalloc(dev, sizeof(*nct6694), GFP_KERNEL);
	if (!nct6694)
		return -ENOMEM;

	nct6694->usb_msg = devm_kzalloc(dev, sizeof(union nct6694_usb_msg), GFP_KERNEL);
	if (!nct6694->usb_msg)
		return -ENOMEM;

	nct6694->int_buffer = devm_kzalloc(dev, sizeof(*nct6694->int_buffer), GFP_KERNEL);
	if (!nct6694->int_buffer)
		return -ENOMEM;

	nct6694->int_in_urb = usb_alloc_urb(0, GFP_KERNEL);
	if (!nct6694->int_in_urb)
		return -ENOMEM;

	nct6694->domain = irq_domain_create_simple(NULL, NCT6694_NR_IRQS, 0,
						   &nct6694_irq_domain_ops,
						   nct6694);
	if (!nct6694->domain) {
		ret = -ENODEV;
		goto err_urb;
	}

	nct6694->dev = dev;
	nct6694->udev = udev;

	ida_init(&nct6694->gpio_ida);
	ida_init(&nct6694->i2c_ida);
	ida_init(&nct6694->canfd_ida);
	ida_init(&nct6694->wdt_ida);

	spin_lock_init(&nct6694->irq_lock);

	ret = devm_mutex_init(dev, &nct6694->access_lock);
	if (ret)
		goto err_ida;

	interface = iface->cur_altsetting;

	int_endpoint = &interface->endpoint[0].desc;
	if (!usb_endpoint_is_int_in(int_endpoint)) {
		ret = -ENODEV;
		goto err_ida;
	}

	usb_fill_int_urb(nct6694->int_in_urb, udev, usb_rcvintpipe(udev, NCT6694_INT_IN_EP),
			 nct6694->int_buffer, sizeof(*nct6694->int_buffer), usb_int_callback,
			 nct6694, int_endpoint->bInterval);

	ret = usb_submit_urb(nct6694->int_in_urb, GFP_KERNEL);
	if (ret)
		goto err_ida;

	usb_set_intfdata(iface, nct6694);

	ret = mfd_add_hotplug_devices(dev, nct6694_devs, ARRAY_SIZE(nct6694_devs));
	if (ret)
		goto err_mfd;

	return 0;

err_mfd:

